sys_ux_client_script.required_translations:
[
    {
        "message": "Group created successfully"
    },
    {
        "message": "Failed to create Group"
    },
    {
        "message": "Error Creating Group"
    }
]

sys_ux_client_script.script:
/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
* @param {ApiHelpers} params.helpers
*/
async function handler({ api, event, helpers, imports }) {
    console.log("GroupName:", api.state.GrpName);

    var requestData = {
        "groupName":  api.state.GrpName ,
        "roles": api.state.role
    };

    console.log("RequestBody before" , requestData)
    try {
        // Use snHttp to send the API request
        const response = await helpers.snHttp(
            "/api/985627/custom_add_group",
            {
                method: "POST",
                headers: {
                    "Content-Type": "application/json"
                },
                body: JSON.stringify(requestData)
            }
        );

        // Log the response for verification
        console.log("Response status 1:", response.response.result.success);
        console.log("Response status 2:", response.result);
        console.log("Response body:", response);

        // Process the API response correctly
        if (response.response.result.success) {
            console.log(`Group created successfully`);

            api.emit('NOW_UXF_PAGE#ADD_NOTIFICATIONS', {
                items: [
                    {
                        id: 'alert2',
                        status: 'positive',
                        icon: 'info-circle-outline',
                        content: await helpers.translate('Group created successfully'),
                        action: { type: 'dismiss' }
                    }
                ]
            });
        } else {
            console.error(`Failed to update Property`, response);

            api.emit('NOW_UXF_PAGE#ADD_NOTIFICATIONS', {
                items: [
                    {
                        id: 'alert2',
                        status: 'critical',
                        icon: 'info-circle-outline',
                        content: await helpers.translate('Failed to create Group'),
                        action: { type: 'dismiss' }
                    }
                ]
            });
        }
    } catch (error) {
        // Handle any errors in the API call
        console.error(`Error updating Group:`, error.message || error);

        api.emit('NOW_UXF_PAGE#ADD_NOTIFICATIONS', {
            items: [
                {
                    id: 'alert2',
                    status: 'critical',
                    icon: 'info-circle-outline',
                    content: await helpers.translate('Error Creating Group'),
                    action: { type: 'dismiss' }
                }
            ]
        });
    }
}
